"""Index: topic entries and descriptive reference cards.

kind = "topic" | "card". Cards are descriptive only. No licensed scale is reproduced
with its scoring; see shared standards (licensed scales replaced by descriptive cards).
Each entry: id, title, kind, category, summary, assess[], interventions[], pitfalls[], flags[].
"""

def e(id, title, category, summary, assess, interventions, pitfalls=(), flags=(), kind="topic"):
    return dict(id=id, title=title, kind=kind, category=category, summary=summary,
                assess=list(assess), interventions=list(interventions),
                pitfalls=list(pitfalls), flags=list(flags))

